<?php
namespace App\Http\Controllers\Admin;
use App\Domain\Media\{MediaCacheInvalidator,MediaRegistry}; use App\Http\Controllers\Controller; use App\Models\{MediaAsset,MediaUsage}; use Illuminate\Http\{RedirectResponse,Request};
class MediaUsageController extends Controller
{
 public function store(Request $request,string $type,int $id,MediaCacheInvalidator $cache):RedirectResponse{$definition=MediaRegistry::definition($type);$validated=$request->validate(['media_asset_uuid'=>['required','uuid'],'slot'=>['required','string','max:60'],'display_order'=>['nullable','integer','between:1,1000']]);MediaRegistry::assertSlot($type,$validated['slot']);$mediable=$definition['class']::query()->findOrFail($id);$asset=MediaAsset::query()->selectable()->where('uuid',$validated['media_asset_uuid'])->firstOrFail();$multiple=in_array($validated['slot'],$definition['multiple'],true);$order=$multiple?($validated['display_order']??((int)MediaUsage::query()->whereMorphedTo('mediable',$mediable)->where('slot',$validated['slot'])->max('display_order')+1)):1;if(!$multiple){MediaUsage::query()->whereMorphedTo('mediable',$mediable)->where('slot',$validated['slot'])->delete();}MediaUsage::query()->create(['media_asset_id'=>$asset->id,'mediable_type'=>$type,'mediable_id'=>$mediable->getKey(),'slot'=>$validated['slot'],'display_order'=>$order]);$cache->invalidate($asset);return back()->with('status','Canonical media selected. Legacy path retained as fallback.');}
 public function destroy(string $type,int $id,MediaUsage $mediaUsage,MediaCacheInvalidator $cache):RedirectResponse{$definition=MediaRegistry::definition($type);abort_unless($mediaUsage->mediable_type===$type&&$mediaUsage->mediable_id===$id&&$mediaUsage->mediable instanceof $definition['class'],404);$asset=$mediaUsage->asset;$mediaUsage->delete();$cache->invalidate($asset);return back()->with('status','Canonical media detached; the legacy fallback remains unchanged.');}
}
